import base64
import json
import os
import random
import time
import uuid

import boto3

BUCKET_NAME = os.environ["CAT_PICTURES_BUCKET"]
TABLE_NAME = os.environ["CAT_METADATA_TABLE"]

s3_client = boto3.client("s3")
cat_table = boto3.resource("dynamodb").Table(TABLE_NAME)


def build_response(status_code, body, headers=None, is_base64_encoded=False):
    return {
        "statusCode": status_code,
        "headers": headers or {"Content-Type": "application/json"},
        "isBase64Encoded": is_base64_encoded,
        "body": body,
    }


def json_response(status_code, payload):
    return build_response(status_code, json.dumps(payload))


def request_content_type(event):
    headers = event.get("headers") or {}
    for name, value in headers.items():
        if str(name).lower() == "content-type" and value:
            candidate = str(value)
            if candidate.lower().startswith("image/"):
                return candidate
    return "image/jpeg"


def extract_image_bytes(event):
    body = event.get("body") or ""
    if not body:
        raise ValueError("empty request body")
    if event.get("isBase64Encoded"):
        decoded = base64.b64decode(body)
        try:
            body = decoded.decode("utf-8")
        except UnicodeDecodeError:
            return decoded
    return base64.b64decode(body)


def upload_cat(event):
    try:
        image_bytes = extract_image_bytes(event)
    except (ValueError, TypeError):
        return json_response(
            400,
            {"message": "Request body must contain a base64-encoded cat picture."},
        )
    if not image_bytes:
        return json_response(400, {"message": "Request body must not be empty."})

    image_id = str(uuid.uuid4())
    s3_key = f"cat-pictures/{image_id}"
    content_type = request_content_type(event)

    s3_client.put_object(
        Bucket=BUCKET_NAME,
        Key=s3_key,
        Body=image_bytes,
        ContentType=content_type,
    )
    cat_table.put_item(
        Item={
            "ImageId": image_id,
            "S3Key": s3_key,
            "ContentType": content_type,
            "UploadedAt": int(time.time()),
        }
    )
    return json_response(201, {"imageId": image_id, "s3Key": s3_key})


def random_cat(event):
    items = []
    scan_kwargs = {"ProjectionExpression": "ImageId, S3Key, ContentType"}
    while True:
        result = cat_table.scan(**scan_kwargs)
        items.extend(result.get("Items", []))
        last_evaluated_key = result.get("LastEvaluatedKey")
        if not last_evaluated_key:
            break
        scan_kwargs["ExclusiveStartKey"] = last_evaluated_key

    if not items:
        return json_response(
            404,
            {"message": "No cat pictures available yet. Upload one with POST /cats."},
        )

    chosen = random.choice(items)
    presigned_url = s3_client.generate_presigned_url(
        "get_object",
        Params={"Bucket": BUCKET_NAME, "Key": chosen["S3Key"]},
        ExpiresIn=300,
    )
    return json_response(
        200,
        {
            "imageId": chosen["ImageId"],
            "s3Key": chosen["S3Key"],
            "contentType": chosen.get("ContentType", "image/jpeg"),
            "imageUrl": presigned_url,
        },
    )


def handler(event, context):
    http_method = (event.get("httpMethod") or "").upper()
    path = event.get("path") or ""
    route = f"{http_method} {path}"

    if route == "POST /cats":
        return upload_cat(event)
    if route == "GET /cats/random":
        return random_cat(event)
    return json_response(404, {"message": f"Unsupported route: {route}"})
